Method.Implementation:
Quit:'$IsObject(pRequest.Stream) $$$ERROR($$$EnsErrGeneral,"No Stream contained in StreamContainer Request") Set tNameIn=##class(%File).GetFilename(pRequest.OriginalFilename) Set (tFilename,tFinalFilename)=..Adapter.CreateTimestamp(tNameIn,..Filename) If ""'=..TempFilename { Set tFilename=..Adapter.CreateTimestamp(tNameIn,..TempFilename) } Set tSC=..Adapter.PutStream(tFilename, pRequest.Stream) If tFinalFilename'=tFilename&&$$$ISOK(tSC) Set tSC=..Adapter.Rename(tFilename, tFinalFilename)
// For this Retry logic to work, Opeeration Setting "Reply Code Actions" should have a code with R , e.g E=RD or E=RF $$$TRACE("Current Retry Count : "_..RetryCount) set MaxRetry = (..FailureTimeout/..RetryInterval)+1 $$$TRACE(..FailureTimeout_" **** "_..RetryInterval_" ***** "_"Max retry : "_MaxRetry)
Set currentDate = $ZDATETIME($ZTIMESTAMP,3,3) Set extractDate = $EXTRACT(currentDate,0,11) Set extractTime = $EXTRACT(currentDate,11,$LENGTH(currentDate))
do ..valueToBeReplaced.SetAt(tFinalFilename,"%FN") do ..valueToBeReplaced.SetAt(extractDate,"%CD") do ..valueToBeReplaced.SetAt(extractTime,"%CT") IF (pRequest.%IsA("IHC.ITF.ITFCOMMON.DataStructure.StreamWithFilePath")) { do ..valueToBeReplaced.SetAt(pRequest.NewFilePath, "%DEST") }
Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(..SuccessEmailSubject) Set updatedFailureEmailSubject = ..replaceWithParticularFormat(..FailureEmailSubject) Set updatedSuccessEmailbody = ..replaceWithParticularFormat(..SucessEmailBody) Set updatedFailureEmailbody = ..replaceWithParticularFormat(..FailureEmailBody)
$$$TRACE("Retry:"_..Retry) $$$TRACE("FailureTimeOut:"_..FailureTimeout) //Sending Email If $$$ISOK(tSC) { $$$TRACE("Sending alert for successful file transfer.") ;set alert.AlertText=$$$ITFCOMMONSendEmailOnSuccess _ ":emailSubject: "_..EmailSubject_" emailBody:"_..EmailBody ;do ..valueToBeReplaced.SetAt("Success","%EM") do ..ItfSendEmailOnSuccess(updatedSuccessEmailSubject, updatedSuccessEmailbody) } ElseIf(..RetryCount=MaxRetry) { $$$TRACE(MaxRetry_" Retry Count inside else part : "_..RetryCount) $$$TRACE("Sending alert for failure in file transfer.") ;set alert.AlertText=$$$ITFCOMMONSendEmailOnSuccess _ ":emailSubject: "_..EmailSubject_" emailBody:"_..EmailBody do ..valueToBeReplaced.SetAt(tSC,"%EM") Set updatedFailureEmailSubject = ..replaceWithParticularFormat(updatedFailureEmailSubject) Set updatedFailureEmailbody = ..replaceWithParticularFormat(updatedFailureEmailbody) do ..ItfSendEmailOnError(updatedFailureEmailSubject, updatedFailureEmailbody) } if ' ..PassBackErrors { set tSC = $$$OK } Quit tSC
